import{_ as e,c as l,o as r,ah as i}from"./chunks/framework.Dnh4IO1K.js";const b=JSON.parse('{"title":"地火明夷","description":"周易折中 - 地火明夷","frontmatter":{"title":"地火明夷","description":"周易折中 - 地火明夷"},"headers":[],"relativePath":"zh/classics/zhezhong/042.md","filePath":"zh/classics/zhezhong/042.md"}'),h={name:"zh/classics/zhezhong/042.md"};function p(n,a,d,t,s,o){return r(),l("div",null,[...a[0]||(a[0]=[i('<h1 id="地火明夷" tabindex="-1">地火明夷 <a class="header-anchor" href="#地火明夷" aria-label="Permalink to “地火明夷”">​</a></h1><h3 id="程传" tabindex="-1">程传 <a class="header-anchor" href="#程传" aria-label="Permalink to “程传”">​</a></h3><p>〈明夷序卦〉：“晋者，进也；进必有所伤，故受之以明夷。夷者，伤也。夫进之不已，必有所伤，理自然也。明夷所以次晋也。为卦坤上离下，明入地中也。反晋成明夷，故义与晋正相反。晋者，明盛之卦，明君在上，群贤并进之时也。明夷，昏暗之卦，暗君在上，明者见伤之时也。日入于地中，明伤而昏暗也，故为明夷。”</p><p>明夷：利艰贞</p><h3 id="本义" tabindex="-1">本义 <a class="header-anchor" href="#本义" aria-label="Permalink to “本义”">​</a></h3><p>夷，伤也。为卦下离上坤，日入地中，明而见伤之象，故为明夷。又其上六为暗之主，六五近之，故占者利于艰难以守正而自晦其明也。</p><h3 id="程传-1" tabindex="-1">程传 <a class="header-anchor" href="#程传-1" aria-label="Permalink to “程传”">​</a></h3><p>君子当明夷之时，利在知艰难而不失其贞正也。在昏暗艰难之时而能不失其正，所以为明君子也。</p><h3 id="集说" tabindex="-1">集说 <a class="header-anchor" href="#集说" aria-label="Permalink to “集说”">​</a></h3><ul><li><p>孔氏颖逹曰 ：时虽至暗，不可随世倾邪，故宜艰难坚固守其贞正之德。</p></li><li><p>李氏舜臣曰 ：易卦诸爻，噬嗑之九四、大畜之九三曰“利艰贞”，未有一卦全体以利艰贞为义者。此盖睹君子之明伤为可惧，而危辞以戒之，其时可知也。</p></li><li><p>胡氏炳文曰 ：以二体则离明也，伤之者坤；以六爻则初至五皆明也，伤之者上。上为暗主，而五近之，故本义从彖传以利艰贞为五。</p></li></ul><p>象曰：明入地中，明夷；君子以莅众用晦而明</p><h3 id="程传-2" tabindex="-1">程传 <a class="header-anchor" href="#程传-2" aria-label="Permalink to “程传”">​</a></h3><p>明所以照，君子无所不照。然用明之过，则伤于察，太察则尽事而无含弘之度。故君子观明入地中之象，于莅众也，不极其明察而用晦，然后能容物和众，众亲而安。是用晦乃所以为明也。若自任其明，无所不察，则己不胜其忿疾，而无寛厚含容之德，人情睽疑而不安，失莅众之道，适所以为不明也。古之圣人设前旒、屏树者，不欲明之尽乎隐也。</p><h3 id="集说-1" tabindex="-1">集说 <a class="header-anchor" href="#集说-1" aria-label="Permalink to “集说”">​</a></h3><ul><li><p>孔氏颖达曰：冕旒垂目，黈纩塞耳，无为清静，民化不欺。若运其聪明显其智慧，民即逃其密网，奸诈愈生。岂非藏明用晦，反得其明也？</p></li><li><p>张子曰：不任察而不失其治也。</p></li><li><p>林氏希元曰：用晦而明，不是以晦为明，亦不是晦其明。盖虽明而用晦，虽用晦而明也。用晦而明，只是不尽用其明。盖尽用其明，则伤于太察而无含弘之道。惟明而用晦，则既不汶汶而暗，亦不察察而明。虽无所不照，而有不尽照者，此古先帝王所以莅众之术也。</p></li><li><p>何氏楷曰：晦其明谓藏明于晦，晦而明谓生明于晦，意实相发。</p></li></ul><p>彖曰：明入地中，明夷</p><h3 id="本义-1" tabindex="-1">本义 <a class="header-anchor" href="#本义-1" aria-label="Permalink to “本义”">​</a></h3><p>以卦象释卦名。</p><h3 id="集说-2" tabindex="-1">集说 <a class="header-anchor" href="#集说-2" aria-label="Permalink to “集说”">​</a></h3><ul><li>孔氏颖逹曰 ：此就二象以释卦名，此及晋卦皆彖象同辞也。</li></ul><p>内文明而外柔顺，以蒙大难，文王以之</p><h3 id="本义-2" tabindex="-1">本义 <a class="header-anchor" href="#本义-2" aria-label="Permalink to “本义”">​</a></h3><p>以卦德释卦义。蒙大难，谓遭纣之乱而见囚也。</p><h3 id="程传-3" tabindex="-1">程传 <a class="header-anchor" href="#程传-3" aria-label="Permalink to “程传”">​</a></h3><p>明入于地，其明灭也，故为明夷。内卦离，离者文明之象；外卦坤冲，者柔顺之象。为人内有文明之德，而外能柔顺也。昔者文王如是，故曰“文王以之”。当纣之昏暗，乃明夷之时，而文王内有文明之德，外柔顺以事纣，蒙犯大难而内不失其明圣，而外足以逺祸患。此文王所用之道也，故曰“文王以之”。</p><p>利艰贞，晦其明也。内难而能正其志，箕子以之</p><h3 id="本义-3" tabindex="-1">本义 <a class="header-anchor" href="#本义-3" aria-label="Permalink to “本义”">​</a></h3><p>以六五一爻之义释卦辞。内难，谓为纣近亲，在其国内（知六五之近于上六也）。</p><h3 id="程传-4" tabindex="-1">程传 <a class="header-anchor" href="#程传-4" aria-label="Permalink to “程传”">​</a></h3><p>明夷之时，利于处艰厄而不失其贞正，谓能晦藏其明也。不晦其明，则被祸患；不守其正，则非贤明。箕子当纣之时，身处其国内，切近其难，故云“内难”。然箕子能藏晦其明而自守其正志，箕子所用之道也，故曰“箕子以之”。</p><h3 id="集说-3" tabindex="-1">集说 <a class="header-anchor" href="#集说-3" aria-label="Permalink to “集说”">​</a></h3><ul><li><p>胡氏炳文曰 ：六五爻辞曰“箕子之明夷，利贞”，释彖兼文王发之。盖羑里演易处之甚从容，可见文王之德；佯狂受辱处之极艰难，可见箕子之志。然此一时也，文王因而发伏羲之易，箕子因而发大禹之畴。圣贤之于患难，自系斯文之㑹，盖有天意存焉。</p></li><li><p>俞氏琰曰 ：大难谓羑里之囚也，其难闗系天下之大，民命之所寄，故曰大难。内难谓家难也，其难闗系一家之内，宗社之所寄也。箕子为纣之近亲，故曰内难。</p></li></ul><p>初九：明夷于飞，垂其翼；君子于行，三日不食；有攸往，主人有言。</p><h3 id="本义-4" tabindex="-1">本义 <a class="header-anchor" href="#本义-4" aria-label="Permalink to “本义”">​</a></h3><p>飞而垂翼，见伤之象。占者行而不食，所如不合时义，当然不得而避也。</p><h3 id="程传-5" tabindex="-1">程传 <a class="header-anchor" href="#程传-5" aria-label="Permalink to “程传”">​</a></h3><p>初九明体，而居明夷之初，见伤之始也。九，阳明上升者也，故取飞象。昏暗在上，伤阳之明，使不得上进，是于飞而伤其翼也。翼见伤，故垂朵。凡小人之害君子，害其所以行者。“君子于行，三日不食”，君子明照，见事之微，虽始有见伤之端，未显也，君子则能见之矣，故行去避之。“君子于行”，谓去其禄位而退藏也。“三日不食”，言困穷之极也。事未显而处甚艰，非见几之明不能也。夫知几者，君子之独见，非众人所能识也。故明夷之始，其见伤未显而去之，则世俗孰不疑怪？故有所往适，则主人有言也。然君子不以世俗之见怪而迟疑其行也。若俟众人尽识，则伤己及而不能去矣。此薛方所以为明而扬雄所以不获其去也。或曰：“伤至于垂翼，伤已明矣，何得众人犹未识也？”曰：“初伤之始也，云垂其翼，谓伤其所以飞尔，其事则未显也。”君子见几，故亟去之，世俗之人未能见也，故异而非之。如穆生之去楚，申公、白公且非之，况世俗之人乎？但讥其责小礼而不知穆生之去避胥靡之祸也。当其言曰：“不去，楚人将钳我于市。”虽二儒者亦以为过甚之言也。又如袁闳于党事未起之前，名德之士方锋起而独潜身土室，故人以为狂生，卒免党锢之祸。所往而人有言，何足怪也。</p><h3 id="集说-4" tabindex="-1">集说 <a class="header-anchor" href="#集说-4" aria-label="Permalink to “集说”">​</a></h3><ul><li><p>兰氏廷瑞曰 ：阳刚之君子，居明夷之始，戢翼避祸，见几先遁。</p></li><li><p>项氏安世曰 ：垂其翼，不言夷未伤也；夷于左股，言已伤也。说者以垂其翼为伤翼，非也。敛翼而下飞者，避祸之象也。</p></li><li><p>丘氏富国曰 ：初体离明，去上最远，见伤即避，有飞而垂翼之象。君子知几，义当速去，盖可以不食而不可以不去，去重于食故也。</p></li><li><p>俞氏琰曰 ：居明夷之初，不敢高飞，遂垂敛其翼以向下，此见几之明，不待难作而早避者也。夫知几而早去，此君子独见，主人固不识也，岂得无言？</p></li></ul><p>象曰：君子于行义，不食也</p><h3 id="本义-5" tabindex="-1">本义 <a class="header-anchor" href="#本义-5" aria-label="Permalink to “本义”">​</a></h3><p>唯义所在，不食可也</p><h3 id="程传-6" tabindex="-1">程传 <a class="header-anchor" href="#程传-6" aria-label="Permalink to “程传”">​</a></h3><p>君子遁藏而困穷，义当然也。唯义之当然，故安处而无闷，虽不食可也。</p><h3 id="集说-5" tabindex="-1">集说 <a class="header-anchor" href="#集说-5" aria-label="Permalink to “集说”">​</a></h3><p>王氏申子曰：义所不食，则于飞攸往；义所当行，亦明矣。去之可不速乎？此伯夷、太公之事。</p><p>六二：明夷，夷于左股，用拯马壮，吉。</p><h3 id="本义-6" tabindex="-1">本义 <a class="header-anchor" href="#本义-6" aria-label="Permalink to “本义”">​</a></h3><p>伤而未切，救之速则免矣，故其象占如此。</p><h3 id="程传-7" tabindex="-1">程传 <a class="header-anchor" href="#程传-7" aria-label="Permalink to “程传”">​</a></h3><p>六二以至明之才，得中正而体顺，顺时自处，处之至善也。虽君子自处之善，然当阴暗小人伤明之时，亦不免为其所伤。但君子自处有道，故不能深相伤害，终能违避之耳。足者所以行也，股在胫足之上，于行之用为不甚切；左又非便用者，手足之用以右为便，惟蹶张用左，盖右立为本也。夷于左股，谓伤害其行而不甚切也。虽然，亦必自免有道。拯用壮健之马，则获免之速而吉也。君子为阴暗所伤，其自处有道，故其伤不甚；自拯有道，故获免之疾。用拯之道不壮，则被伤深矣，故云马壮则吉也。二以明居阴暗之下，所谓吉者，得免伤害而已，非谓可以有为于斯时也。</p><h3 id="集说-6" tabindex="-1">集说 <a class="header-anchor" href="#集说-6" aria-label="Permalink to “集说”">​</a></h3><ul><li>王氏宗传曰 ：六二文明之主也，以六居二，柔顺之至，文王以之。</li></ul><h3 id="案" tabindex="-1">案 <a class="header-anchor" href="#案" aria-label="Permalink to “案”">​</a></h3><p>明夷与丰卦略相似，然丰者明中之昏，明夷则昏极而不复明也。两卦皆以上六为昏之主，六二为明之主。既为明之主，岂可不以救昏为急？故此之“夷于左股”者，与丰二之“往得疑疾”同也；此之“用拯马壮”者，与丰之“有孚发若”同也。盖未至于丰三之“折其右肱”，则犹有可为之理也。</p><p>象曰：六二之吉，顺以则也</p><h3 id="程传-8" tabindex="-1">程传 <a class="header-anchor" href="#程传-8" aria-label="Permalink to “程传”">​</a></h3><p>六二之得吉者，以其顺处而有法则也。则谓中正之道，能顺而得中正，所以处明夷之时而能保其吉也。</p><h3 id="集说-7" tabindex="-1">集说 <a class="header-anchor" href="#集说-7" aria-label="Permalink to “集说”">​</a></h3><ul><li><p>项氏安世曰：明夷之下三爻，惟六二有救之之诚；上三爻，惟六五无去之之心，皆中顺之臣也。</p></li><li><p>王氏申子曰：以柔顺处之而不失其中正之则，昔者文王用明夷之道，其如是乎？</p></li></ul><p>九三：明夷于南狩，得其大首，不可疾贞。</p><h3 id="本义-7" tabindex="-1">本义 <a class="header-anchor" href="#本义-7" aria-label="Permalink to “本义”">​</a></h3><p>以刚居刚，又在明体之上，而屈于至暗之下，正与上六暗主为应，故有向明除害，得其首恶之象。然不可以亟也，故有不可疾贞之戒。成汤起于夏台，文王兴于羑里，正合此爻之义。而小事亦有然者。</p><h3 id="程传-9" tabindex="-1">程传 <a class="header-anchor" href="#程传-9" aria-label="Permalink to “程传”">​</a></h3><p>九三，离之上，明之极也，又处刚而进。上六，坤之上，暗之极也。至明居下而为下之上，至暗在上而处穷极之地，正相敌应，将以明去暗者也。斯义也，其汤武之事乎？南在前而明方也，狩畋而去害之事也。南狩，谓前进而除害也。当克获其大首，大首谓暗之魁首，上六也。三与上正相应，为至明克至暗之象。不可疾贞，谓诛其元恶，旧染污俗未能遽革，必有其渐。革之遽，则骇惧而不安。故《酒诰》云：“惟殷之迪诸臣，惟工乃湎于酒，毋庸杀之，姑惟教之。”至于既乆，尚曰“馀风未殄”，是渐渍之俗，不可以遽革也。故曰“不可疾贞”，正之不可急也。上六虽非君位，以其居上而暗之极，故为暗之主，谓之大首。</p><h3 id="集说-8" tabindex="-1">集说 <a class="header-anchor" href="#集说-8" aria-label="Permalink to “集说”">​</a></h3><ul><li>胡氏炳文曰 ：二之救难可速也，三之除害不可速也，故有“不可疾贞”之戒。</li></ul><p>象曰：南狩之志，乃大得也</p><h3 id="程传-10" tabindex="-1">程传 <a class="header-anchor" href="#程传-10" aria-label="Permalink to “程传”">​</a></h3><p>夫以下之明除上之暗，其志在去害而已。如商周之汤武，岂有意于利天下乎？得其大首，是能去害而大得其志矣。志苟不然，乃悖乱之事也。</p><p>六四：入于左腹，获明夷之心，于出门庭。</p><h3 id="本义-8" tabindex="-1">本义 <a class="header-anchor" href="#本义-8" aria-label="Permalink to “本义”">​</a></h3><p>此爻之义未详，窃疑左腹者幽隐之处，获明夷之心于出门庭者，得意于远去之义。言筮而得此者，其自处当如是也。盖离体为至明之德，坤体为至暗之地，下三爻明在暗外，故随其远近髙下而处之不同。六四以柔正居暗地而尚浅，故犹可以得意于远去。五以柔中居暗地而已迫，故为内难正志以晦其明之象。上则极乎暗矣，故为自伤其明以至于暗，而又足以伤人之明。盖下五爻皆为君子，独上一爻为暗君也。</p><h3 id="程传-11" tabindex="-1">程传 <a class="header-anchor" href="#程传-11" aria-label="Permalink to “程传”">​</a></h3><p>六四以阴居阴，而在阴柔之体，处近君之位，是阴邪小人居高位以柔邪顺于君者也。六五明夷之君位，伤明之主也。四以柔邪顺从之，以固其交。夫小人之事君，未有由显明以道合者也，必以隐僻之道自结于上。右当用，故为明显之所；左不当用，故为隐僻之所。人之手足皆以右为用，世谓僻所为僻左，是左者隐僻之所也。四由隐僻之道深入其君，故云“入于左腹”，“入腹”谓其交深也。其交之深，故得其心。凡奸邪之见信于其君，皆由夺其心也。不夺其心，能无悟乎？于出门庭，既信之于心，而后行之于外也。邪臣之事暗君，必先蛊其心，而后能行于外。</p><h3 id="集说-9" tabindex="-1">集说 <a class="header-anchor" href="#集说-9" aria-label="Permalink to “集说”">​</a></h3><ul><li><p>杨氏时曰 ：腹，坤象也，坤体之下，故曰左腹（尊右故也）。获明夷之心，所谓求仁而得仁也。此君子之明夷也。</p></li><li><p>朱子语类云 ：明夷下三爻皆说明夷是明而见伤者，六四说者却以为奸邪之臣先蛊惑其君心而后肆行于外。下三爻皆说明夷是好底，何独此爻却作不好说？以意观之，六四居暗地尚浅，犹可以得意而远去，故虽入于幽隐之处，犹能获明夷之心于出门庭也。上六不明晦，则是合下已是不明。</p></li><li><p>胡氏炳文曰 ：初二三在暗外，至四则将入暗中，然比之六五，则四尚浅也，犹可得意于远去。获明夷之心者，微子之自靖于出门庭者，君子之行遁也。</p></li></ul><p>象曰：入于左腹，获心意也</p><h3 id="程传-12" tabindex="-1">程传 <a class="header-anchor" href="#程传-12" aria-label="Permalink to “程传”">​</a></h3><p>入于左腹，谓以邪僻之道入于君而得其心意也。得其心，所以终不悟也。</p><p>六五：箕子之明夷，利贞</p><h3 id="本义-9" tabindex="-1">本义 <a class="header-anchor" href="#本义-9" aria-label="Permalink to “本义”">​</a></h3><p>居至暗之地，近至暗之君，而能正其志，箕子之象也。贞之至也，利贞以戒占者。</p><h3 id="程传-13" tabindex="-1">程传 <a class="header-anchor" href="#程传-13" aria-label="Permalink to “程传”">​</a></h3><p>五为君位，乃常也。然《易》之取义，变动随时。上六处坤之上，而明夷之极，阴暗伤明之极者也。五切近之，圣人因以五为切近至暗之人，以见处之之义，故不专以君位言。上六阴暗伤明之极，故以为明夷之主。五切近伤明之主，若显其明，则见伤害必矣。故当如箕子之自晦藏，则可以免于难。箕子，商之旧臣而同姓之亲，可谓切近于纣矣。若不自晦其明，被祸可必也。故佯狂为奴，以免于害。虽晦藏其明，而内守其正，所谓内难而能正其志，所以谓之仁与明也。若箕子可谓贞矣。以五阴柔，故为之戒云“利贞”，谓宜如箕子之贞固也。若以君道言，义亦如是。人君有当含晦之时，亦外晦其明而内正其志也。</p><p>象曰：箕子之贞，明不可息也</p><h3 id="程传-14" tabindex="-1">程传 <a class="header-anchor" href="#程传-14" aria-label="Permalink to “程传”">​</a></h3><p>箕子晦藏不失其贞固，虽遭患难，其明自存，不可灭息也。若逼祸患遂失其所守，则是亡其明，乃灭息也。古之人如扬雄者是也。</p><h3 id="集说-10" tabindex="-1">集说 <a class="header-anchor" href="#集说-10" aria-label="Permalink to “集说”">​</a></h3><p>苏氏轼曰：六五之于上六，正之则势不敌，救之则力不能，去之则义不可，此最难处者也。如箕子而后可。箕子之处于此，身可辱也，而明不可息也。</p><p>上六：不明晦，初登于天，后入于地</p><h3 id="本义-10" tabindex="-1">本义 <a class="header-anchor" href="#本义-10" aria-label="Permalink to “本义”">​</a></h3><p>以阴居坤之极，不明其德，以至于晦。始则处高位以伤人之明，终必至于自伤而坠厥命。故其象如此，而占亦在其中矣。</p><h3 id="程传-15" tabindex="-1">程传 <a class="header-anchor" href="#程传-15" aria-label="Permalink to “程传”">​</a></h3><p>上居卦之终，为夷明之主，又为明夷之极。上至髙之地，明在至髙，本当远照，明既夷伤，故不明而反昏晦也。本居于高明，当及远，初登于天也，乃夷伤其明而昏暗，后入于地也。上明夷之终，又坤阴之终，明伤之极者也。</p><h3 id="集说-11" tabindex="-1">集说 <a class="header-anchor" href="#集说-11" aria-label="Permalink to “集说”">​</a></h3><ul><li>苏氏轼曰 ：六爻皆晦也，而所以晦者不同。自五以下，明而晦者也；若上六，不明而晦者也。故曰“不明晦”。</li></ul><p>苏氏轼曰 ：六爻皆晦也，而所以晦者不同。自五以下，明而晦者也；若上六，不明而晦者也。故曰“不明晦”。</p><ul><li>胡氏炳文曰 ：下三爻以“明夷”为句首，四、五“明夷”之辞在句中，上六不曰“明夷”而曰“不明晦”，盖惟上六不明而晦，所以五爻之明皆为其所夷也。</li></ul><p>胡氏炳文曰 ：下三爻以“明夷”为句首，四、五“明夷”之辞在句中，上六不曰“明夷”而曰“不明晦”，盖惟上六不明而晦，所以五爻之明皆为其所夷也。</p><p>象曰：初登于天，照四国也；后入于地，失则也</p><h3 id="本义-11" tabindex="-1">本义 <a class="header-anchor" href="#本义-11" aria-label="Permalink to “本义”">​</a></h3><p>照四国以位言</p><h3 id="程传-16" tabindex="-1">程传 <a class="header-anchor" href="#程传-16" aria-label="Permalink to “程传”">​</a></h3><p>初登于天，居高而明，则当照及四方也。乃被伤而昏暗，是后入于地，失明之道也。失则，失其道也。</p><h3 id="集说-12" tabindex="-1">集说 <a class="header-anchor" href="#集说-12" aria-label="Permalink to “集说”">​</a></h3><p>胡氏炳文曰：则者，不可逾之理。失则，所以为纣；顺则，所以为文王。</p><p>总论</p><p>苏氏轼曰 ：力能救则救之，六二之用拯是也；力能正则正之，九三之南狩是也。既不能救，又不能正，君子不敢辞其辱以私便其身，六五之箕子是也。君子居明夷之世，有责必有以塞之，无责必有以全其身而不失其正。初九、六四无责于斯世，故近者则入腹获心于出门庭，而远者则行不及食也。</p>',109)])])}const m=e(h,[["render",p]]);export{b as __pageData,m as default};
